namespace OpenTPW;

/// <summary>
/// The path builder's approximation register (docs/PATHS.md; docs/reverse/PATH-plan.md §10). Each entry is
/// tagged <c>[APPROX:PATH-NNN]</c> at its code site and names the plan's unknown in its first word. Everything
/// else in the path builder is traced from the Mac binary (BIN labels at the code sites).
/// </summary>
public static class PathApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("PATH-001", "PATH-ENTER: a left click on an object-less cell (hover state 2, help 441) or a path cell (state 1, help 442) enters the path tool (tp.exe click dispatch 0x4879d0 builds the tool object 0x46c580(1), whose enter 0x46d5a0 calls SetMode(1) 0x52f200); the click's release sets that cell as the start only when the start check 0x535670(1, 0) does not refuse it (0x527222..0x5272b8), else the tool stays on without a start; OpenTPW instead refuses to enter when CheckCell fails, the re-preview while game+36 is set (0x5249b6) is not modelled, and the release-time ghost gate (0x524a63) is modelled for clicks after a start (CellBuildTool.Click) but not for the entering click"),
		("PATH-005", "PATH-REMOVE: the forced path removal (a = b = 0, NoModify respected, no refund) is the original's area clear (tool mode 0x3a from the Delete key handler 0x40c5e0: two clicks span a rectangle and 0x52bdd0 calls ClearCell 0x5367a0(0, 0) on every type-1 cell, 0x52c11f), which Remove matches; OpenTPW's remove tool is one click that clears an object, else a queue cell, else a path cell, while the original's rectangle removes only objects wholly inside it and type-1 path cells and leaves queue and type-10 cells"),
		("PATH-006", "PATH-SLOPE: no slope or height test, as in the original (tp.exe LayLine 0x536100, SetCell 0x532fc0 reads heights only for the ghost, validator 0x535670 has no float operation, SetCellType 0x5346d0); the object terrain rule OpenTPW applies (water, blocked, entrance area, fixed walkway, holes) stands in for the original's cell types: map init 0x536490 types only hole cells (2, 0x1e, 7, refused by type) and leaves every other non-InitialPath cell type 0 (the unowned flag 0x40 is modelled, PATH-007)"),
		("PATH-007", "PATH-LAND: the land follows the original (tp.exe map init 0x536490 sets flag 0x40 on every non-InitialPath cell, the fence of the theme's Hoardings.sam is laid from the gate posts (0x5323f0), an imported save keeps its saved mFlags and hoardings (0x4d0b30), Buy Land validates (0x531a50), prices (0x532303) and merges (0x5327e0) a rectangle), except that the fence fill's cell outcome is modelled (the cells inside the ring closed along the gate, plus the four cells round each corner that turns away from the land; cell for cell equal to the Jungle Easymode save's flags) instead of its 2 x 2 scan (0x5311c0); the six-click fence laid when bit 0x400 of the level word 0x79d86c is set is not modelled; a purchase covering the open side of the gate, or whose merged fence cannot be walked from post A to post B, is refused (the original's validator accepts some such rectangles, e.g. Jungle (45, 11)-(49, 17); its ring walk 0x52ba50 then likely keeps the old ring and the refill drops the new hoardings, charging for no land, or may not terminate)"),
		("PATH-008", "PATH-CODE8: path over any queue cell is refused; the original's validator returns code 8 for a queue end (one link whose neighbour is a queue; tp.exe 0x535670 at 0x535d00), and code 8 is not a refusal: the start check (0x527280) and the ghost accept it, and the commit's SetCellType (0x5346d0; rule 0x535600 allows type 1 over type 3) turns the queue end into a charged path cell; OpenTPW has no queue-to-path conversion"),
		("PATH-013", "PATH-PAUSE: while the pause menu is shown the park takes no tool clicks, as in the original (tp.exe gate 0x48c8d0 reads the pause-menu object 0x7c2534 +0xc; the park click handler 0x4879d0 returns before the tool dispatch); OpenTPW's speed pause keeps the tool live; the original's pause key P (0x40bf70 → 0x409350(1)) also toggles a window (0x48a720 → 0x4a27f0 → 0x47ed80): a full-screen layer (0x65dd7b(1, 1, 1, 0, 0, 0x7ff, 0x5ff), the 'lolight' backdrop) under the panel 5094 (174,500)-(1874,900) of table 0x752e00, and the park click handler 0x4879d0 does not read the pause flag 0x786b84"),
		("PATH-014", "PATH-VARIANT: built straights and edges pick str1/str2 and edg1/edg2 by a hash of the cell (saved cells keep theirs); the original's chooser (tp.exe 0x535dd0) uses the second texture (2 becomes 19, 10 becomes 20) when byte 0x820ac0 is set (0x535fcc), and every call that reaches its end stores rand() & 1 there (CRT rand 0x67b5c0, store 0x53602c, seeded with GetTickCount at 0x54dddc), so each recomputation re-rolls from a shared clock-seeded generator and no per-cell rule exists"),
		("PATH-015", "QUEUE-TEXTURES: queue cells are drawn with QueueTex ground textures whose shape and turn follow decoded artwork and queue links; the original applies no QueueTex texture: its tile refresh 0x5365d0 sends a queue cell's class-2 result of the chooser 0x535dd0 (table 0x7630b0) to 0x5229e0, which places one of the queue models loaded by 0x522900 (quedead, questra, quebnd2, quebnd1, queend, quebin1, quebin2 .md2) turned by 360 minus the rotation, and gives the ground only the sentinel (0, 8, 0); OpenTPW does not draw these models")
	};
}
